import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as r}from"./app-fnFKaiE5.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S07/S07E15.html","title":"S07E15 The One with Joey's New Brain","lang":"zh-CN","frontmatter":{"title":"S07E15 The One with Joey's New Brain","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":161},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":38.54,"words":11561},"filePathRelative":"语言/英语/Friends老友记/S07/S07E15.md"}`),a={name:`S07E15.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-with-joey-s-new-brain" tabindex="-1"><a class="header-anchor" href="#the-one-with-joey-s-new-brain"><span>The One with Joey&#39;s New Brain</span></a></h1><blockquote><p><em>乔伊的新大脑</em></p></blockquote><p>The One With Joey’s New Brain</p><blockquote><p>有乔伊新大脑的那个</p></blockquote><p><strong>Teleplay by:</strong> Andrew Reich &amp; Ted Cohen</p><blockquote><p>安德鲁·里奇和特德·科恩</p></blockquote><p><strong>Story by:</strong> Sherry Bilsing &amp; Ellen Plummer</p><blockquote><p>雪莉·比尔辛和艾伦·普卢默</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, Monica, Chandler, Ross, and Rachel are sitting around the table.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒、莫妮卡、钱德勒、罗斯和瑞秋围坐在桌旁。</em></p></blockquote><p><strong>Monica Geller:</strong> I’m glad you’re here, we have a couple of things to ask you about the wedding ceremony.</p><blockquote><p>很高兴你能来，我们有几件事要问你关于婚礼的事。</p></blockquote><p><strong>Rachel Green:</strong> (starting to cry) Ohh…</p><blockquote><p>（开始哭）哦…</p></blockquote><p><strong>Ross Geller:</strong> What’s the matter? You okay?</p><blockquote><p>怎么了？你没事吧？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, it’s just y’know…</p><blockquote><p>是的，只是你知道…</p></blockquote><p><strong>Chandler Bing:</strong> (To Ross) Monica said wedding.</p><blockquote><p>（对罗斯）莫妮卡说要结婚。</p></blockquote><p><strong>Monica Geller:</strong> Uh, so anyway, we thought one of you could read something during the ceremony.</p><blockquote><p>嗯，不管怎样，我们认为你们中的一个可以在典礼上读点东西。</p></blockquote><p><strong>Rachel Green:</strong> Oh! I would love to read a poem.</p><blockquote><p>哦！我想读一首诗。</p></blockquote><p><strong>Chandler Bing:</strong> Do you think you could get through a poem?</p><blockquote><p>你觉得你能看完一首诗吗？</p></blockquote><p><strong>Rachel Green:</strong> (crying) It’ll be a short one.</p><blockquote><p>（哭）会很短的。</p></blockquote><p><strong>Monica Geller:</strong> Okay, so Ross will be doing the reading.</p><blockquote><p>好的，那么罗斯会做阅读。</p></blockquote><p><strong>Rachel Green:</strong> Ohhh…</p><blockquote><p>哦…</p></blockquote><p><strong>Ross Geller:</strong> Okay. Yeah, I guess, I guess I could do that too.</p><blockquote><p>好的。是的，我想，我想我也能做到。</p></blockquote><p><strong>Chandler Bing:</strong> Too?</p><blockquote><p>也是吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah, I kind of uh, have something else planned for you guys.</p><blockquote><p>是的，我有点，呃，为你们计划了别的事情。</p></blockquote><p><strong>Monica Geller:</strong> Do you mind telling us what it is?</p><blockquote><p>你介意告诉我们是什么吗？</p></blockquote><p><strong>Ross Geller:</strong> Sorry, I’m kinda keeping this one on the Q.T.</p><blockquote><p>对不起，我有点把这个放在Q.T上了。</p></blockquote><p><strong>Chandler Bing:</strong> Well, whatever it is, I hope it involves winking. (Winks in a spy-type manner.)</p><blockquote><p>不管是什么，我希望这包括眨眼。（以间谍式的方式眨眼。）</p></blockquote><p><strong>Joey Tribbiani:</strong> (entering, excited) Hey!</p><blockquote><p>（进来，兴奋）嘿！</p></blockquote><p><strong>All:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> So I just talked to one of the DOOL writers today, and…</p><blockquote><p>所以我今天刚和一个DOOL的作家谈过，然后…</p></blockquote><p><strong>Monica Geller:</strong> What is DOOL?</p><blockquote><p>杜尔是什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Days Of Our Lives. Anyway, you’re not gonna believe it! My character is coming out of his coma!!</p><blockquote><p>我们生命中的日子。无论如何，你不会相信的！我的角色正从昏迷中苏醒！！</p></blockquote><p><strong>All:</strong> Oh!!</p><blockquote><p>哦！！</p></blockquote><p><strong>Chandler Bing:</strong> That’s great!</p><blockquote><p>太好了！</p></blockquote><p><strong>Joey Tribbiani:</strong> And-and-and not only that, I’m gettin’ a new brain!!</p><blockquote><p>不仅如此，我还有了一个新的大脑！！</p></blockquote><p><strong>Chandler Bing:</strong> So great things are happening at work and in your personal life!</p><blockquote><p>工作和个人生活中都发生了很多大事！</p></blockquote><p><strong>Rachel Green:</strong> Wait, what do you mean you’re getting a new brain?</p><blockquote><p>等等，你说你有了新大脑是什么意思？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh well, they’re killing off one of the characters on the show, and when she dies her brain is being transplanted into my body.</p><blockquote><p>哦，他们正在杀死剧中的一个角色，当她死后，她的大脑正在移植到我的身体里。</p></blockquote><p><strong>Ross Geller:</strong> What? A brain transplant?!</p><blockquote><p>什么？脑移植？！</p></blockquote><p><strong>Joey Tribbiani:</strong> (seriously) Yes, it’s a highly controversial procedure.</p><blockquote><p>（严肃地）是的，这是一个极具争议的程序。</p></blockquote><p><strong>Ross Geller:</strong> It’s ridiculous!</p><blockquote><p>真可笑！</p></blockquote><p><strong>Joey Tribbiani:</strong> Well, I think it’s ridiculous that you haven’t had sex in three and a half months.</p><blockquote><p>嗯，我觉得你已经三个半月没做爱了，这太可笑了。</p></blockquote><p><strong>Ross Geller:</strong> (to Monica and Rachel) It’s winter, they are fewer people on the street. (Rachel and Monica smile and nod, knowingly.)</p><blockquote><p>（对莫妮卡和瑞秋）现在是冬天，街上的人越来越少了。（瑞秋和莫妮卡会意地微笑着点头。）</p></blockquote><p><strong>Monica Geller:</strong> Who are they killing off?</p><blockquote><p>他们在杀谁？</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh Cecilia Monroe, she plays Jessica Lockhart.</p><blockquote><p>塞西莉亚·梦露，她扮演杰西卡·洛克哈特。</p></blockquote><p>Rachel and **Monica Geller: **Noo!!</p><blockquote><p>瑞秋和<strong>莫妮卡·盖勒：</strong>不！！</p></blockquote><p><strong>Monica Geller:</strong> She’s my favorite character on DOOL.</p><blockquote><p>她是我最喜欢的角色。</p></blockquote><p><strong>Joey Tribbiani:</strong> Nice.</p><blockquote><p>很好。</p></blockquote><p><strong>Rachel Green:</strong> She is so good at throwing drinks in people’s faces, I mean I don’t think I’ve ever seen her finish a beverage.</p><blockquote><p>她很会在别人面前扔饮料，我是说我从没见过她喝完一杯。</p></blockquote><p><strong>Monica Geller:</strong> And the way she slaps all the time!</p><blockquote><p>还有她一直打耳光的样子！</p></blockquote><p><strong>Rachel Green:</strong> Oh!</p><blockquote><p>哦！</p></blockquote><p><strong>Monica Geller:</strong> Wouldn’t you love to do it just once?! (Raises her hand towards Chandler.)</p><blockquote><p>你不想只做一次吗？！（她向钱德勒举起手。）</p></blockquote><p><strong>Chandler Bing:</strong> Don’t do it.</p><blockquote><p>别这么做。</p></blockquote><p><strong>Rachel Green:</strong> Cecilia Monroe man, what a great actress.</p><blockquote><p>塞西莉亚·门罗，一个多么伟大的女演员啊。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, tell me about it. And she’s been on the show forever, it’s gonna be really hard to fill her shoes.</p><blockquote><p>哦，告诉我吧。而且她一直都在节目中，这真的很难填补她的位置。</p></blockquote><p><strong>Ross Geller:</strong> Yeah-yeah, help me out here, when you come out of the &quot;brain transplant,&quot; you are going to be her?</p><blockquote><p>是的，是的，帮帮我，当你从“脑移植”中走出来的时候，你会是她吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yes, but in Drake Remoray’s body. (Ross laughs unbelievably.) Why is this so hard for you to get? I thought you were a scientist!</p><blockquote><p>是的，但是在德雷克·雷莫雷的身体里。（罗斯难以置信地笑了起来。）为什么这对你来说这么难？我还以为你是科学家呢！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Phoebe and Rachel sitting on the couch in Central Perk</em></p><blockquote><p>🎬 <em>菲比和瑞秋坐在中央公园的沙发上</em></p></blockquote><p><strong>Phoebe Buffay:</strong> (Clears Throat) Rach, so, that guy there. Straight or gay?</p><blockquote><p>（清了清嗓子）瑞秋，那个家伙。异性恋还是同性恋？</p></blockquote><p><strong>Rachel Green:</strong> (They both look behind them.) Well, I&#39;d have to say gay.</p><blockquote><p>（他们都看了看身后。）嗯，我得说是同性恋。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah? Why?</p><blockquote><p>是吗？为什么？</p></blockquote><p><strong>Rachel Green:</strong> Well mainly because he&#39;s kissing that other guy.</p><blockquote><p>主要是因为他在吻另一个人。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh no not that guy there. That guy right there. (Pointing to an attractive man sitting at a table behind them.)</p><blockquote><p>哦，不，不是那个家伙。就是那个家伙。（指着坐在他们后面桌子旁的一位帅哥。）</p></blockquote><p><strong>Rachel Green:</strong> Oh yeah he&#39;s too cute to be straight.</p><blockquote><p>哦，是的，他太可爱了，不可能是异性恋。</p></blockquote><p><strong>Phoebe Buffay:</strong> (A woman with large breasts walks in the door) Ohh knockers will help us figure it out. (She walks by and he checks her out.)</p><blockquote><p>（一个大乳房的女人走进门）哦，门环会帮我们弄清楚的。（她走过，他检查了一下。）</p></blockquote><p><strong>Rachel Green:</strong> All right, straight, and not subtle. (The man gets up and leaves.)</p><blockquote><p>好吧，直截了当，不含蓄。（那人站起来离开了。）</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh, he left his cell phone.</p><blockquote><p>哦，他把手机忘了。</p></blockquote><p><strong>Rachel Green:</strong> Oh, well, we can hand it to Gunther and he&#39;ll put it in lost and found.</p><blockquote><p>哦，好吧，我们可以把它交给冈瑟，他会把它放在失物招领处。</p></blockquote><p><strong>Phoebe Buffay:</strong> Or we could use it to call China. See how those guys are doing.</p><blockquote><p>或者我们可以用它来称呼中国。看看那些家伙怎么样了。</p></blockquote><p><strong>Rachel Green:</strong> What if, um, if he calls his own cell phone to find out who found it and I answer and we start talking and we fell in love. I mean wouldn&#39;t that be a great story? Kind of like a fairy tale for the digital age.</p><blockquote><p>如果，嗯，如果他打自己的手机找出是谁发现的，我接，然后我们开始交谈，我们相爱了呢。我是说这不是一个很棒的故事吗？有点像数字时代的童话。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah… That does sound great. I&#39;m going to get the phone. (They both get up.)</p><blockquote><p>是的……听起来不错。我去拿电话。（他们俩都站了起来。）</p></blockquote><p><strong>Rachel Green:</strong> What? Wait! Why…why do you get the story?</p><blockquote><p>什么？等待为什么…你为什么知道这个故事？</p></blockquote><p><strong>Phoebe Buffay:</strong> I don&#39;t know. I haven&#39;t been out on a date in so long.</p><blockquote><p>我不知道。我好久没出去约会了。</p></blockquote><p><strong>Rachel Green:</strong> Phoebe, you had a date three days ago.</p><blockquote><p>菲比，你三天前有个约会。</p></blockquote><p><strong>Phoebe Buffay:</strong> That wasn’t a date! That was, that was just friends getting together…(quietly) having sex.</p><blockquote><p>那不是约会！那是，那只是朋友们聚在一起…（静静地）做爱。</p></blockquote><p><strong>Rachel Green:</strong> Okay. Okay, see? I get the phone.</p><blockquote><p>好的。好吧，看到了吗？我去接电话。</p></blockquote><p><strong>Phoebe Buffay:</strong> No way! No way! You just broke with Tag a week ago.</p><blockquote><p>不可能！不可能！你一周前刚和泰格分手。</p></blockquote><p><strong>Rachel Green:</strong> Yeah! (Breaking up) And until now, I didn’t think I’d love again.</p><blockquote><p>是啊！（分手）直到现在，我还以为我不会再爱了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Nice try.</p><blockquote><p>很好的尝试。</p></blockquote><p><strong>Rachel Green:</strong> Oh hey-hey wait! How do we fairly decide who gets the phone?</p><blockquote><p>哦，嘿，等等！我们如何公平地决定谁得到电话？</p></blockquote><p><strong>Phoebe Buffay:</strong> I don’t know.</p><blockquote><p>我不知道。</p></blockquote><p><em>(They edge closer to the phone on the table.)</em></p><blockquote><p><em>（它们靠近桌子上的电话。）</em></p></blockquote><p><strong>Rachel Green:</strong> Well umm, maybe we could uhh… (Grabs the phone) Ah-ha! Too slow!!</p><blockquote><p>嗯，也许我们可以……（拿起电话）啊哈！太慢了！！</p></blockquote><p><em>(She holds the phone out and starts taunting Phoebe. Phoebe calming knocks the phone out of Rachel’s hand and catches it.)</em></p><blockquote><p><em>（她把电话拿出来，开始嘲弄菲比。菲比冷静地把电话从瑞秋手中敲了下来，接住了。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Ah-ha! Too cocky!</p><blockquote><p>啊哈！太骄傲了！</p></blockquote><hr><p>🎬 <em>Silvercup Studios, Joey is watching Jessica Lockhart perform a scene.</em></p><blockquote><p>🎬 <em>银杯工作室，乔伊正在看杰西卡·洛克哈特表演一个场景。</em></p></blockquote><p><strong>Dina:</strong> I’m going to keep dating him Mother, and there’s nothing you can do about it!</p><blockquote><p>我要继续和他约会，妈妈，你对此无能为力！</p></blockquote><p><strong>Jessica Lockhart:</strong> Oh yes there is!</p><blockquote><p>哦，是的！</p></blockquote><p><strong>Dina:</strong> What are you going to do? Kill him? Like you did with Charles?!</p><blockquote><p>你打算怎么办？杀了他？就像你对查尔斯那样？！</p></blockquote><p><strong>Jessica Lockhart:</strong> (gasps) That was an accident! And so were you.</p><blockquote><p>（喘息）那是个意外！你也是。</p></blockquote><p><strong>Dina:</strong> Well, at least I’m not a murderer! (Jessica slaps her.)</p><blockquote><p>嗯，至少我不是杀人犯！（杰西卡扇了她一巴掌。）</p></blockquote><p><strong>Jessica Lockhart:</strong> (crying) Oh, my baby! (Hugs Dina, but moves Dina’s head to her other shoulder so that she’s the only one in the picture.)</p><blockquote><p>（哭）哦，我的宝贝！（拥抱迪娜，但将迪娜的头移到另一个肩膀上，让她成为照片中唯一的一个。）</p></blockquote><p><strong>The Director:</strong> Cut!</p><blockquote><p>停！</p></blockquote><p><em>(Joey walks up to Cecilia Monroe who plays Jessica.)</em></p><blockquote><p><em>（乔伊走向扮演杰西卡的塞西莉亚·门罗。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> That was a great scene! And-and-and that slap looks so real! How do you do that?</p><blockquote><p>那真是一个很棒的场景！而且那一巴掌看起来很真实！你是怎么做到的？</p></blockquote><p><strong>Cecilia:</strong> Oh, just years of experience.</p><blockquote><p>哦，只是几年的经验。</p></blockquote><p><strong>Dina:</strong> (crying) Can I get some ice here?!</p><blockquote><p>（哭）我能在这里弄点冰吗？！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh anyway, I just wanted to say how wonderful I think you are.</p><blockquote><p>哦，不管怎样，我只是想说我觉得你有多棒。</p></blockquote><p><strong>Cecilia:</strong> You’re not the fan who’s dying are you?</p><blockquote><p>你不是即将死去的歌迷，是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Say what?</p><blockquote><p>说什么？</p></blockquote><p><strong>Cecilia:</strong> I’m supposed to meet and hug a fan whose dying, but that’s not supposed to be until (to no one in particular) later!</p><blockquote><p>我本该去见一位歌迷并拥抱他，但我不该在（特别是对任何人）之后才去见他！</p></blockquote><p><strong>Joey Tribbiani:</strong> No. No, I’m Joey Tribbiani; we did a scene together yesterday. I-I’m the guy in the coma!</p><blockquote><p>不，不，我是乔伊·特里比亚尼；我们昨天一起拍了一场戏。我是昏迷中的人！</p></blockquote><p><strong>Cecilia:</strong> Oh that was a real person?!</p><blockquote><p>哦，那是一个真实的人？！</p></blockquote><p><strong>Joey Tribbiani:</strong> An-an-anyway I-I just wanted to say that since I’m getting your brain when you leave the show, I was wondering if there was any tips you can give me…</p><blockquote><p>反正我只是想说，既然你离开节目的时候我就要动你的脑筋了，我想知道你能不能给我点建议…</p></blockquote><p><strong>Cecilia:</strong> I-I-I’m leaving the show?</p><blockquote><p>我-我-我要离开演出了？</p></blockquote><p><strong>Joey Tribbiani:</strong> (quickly) I don’t know. Why? Did you hear something?</p><blockquote><p>（很快）我不知道。为什么？你听到什么了吗？</p></blockquote><p><strong>Cecilia:</strong> Who told you that?</p><blockquote><p>谁告诉你的？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh uh, one of the writers.</p><blockquote><p>哦，嗯，是作家之一。</p></blockquote><p><strong>Cecilia:</strong> Which one? Was it bald or was it tall?</p><blockquote><p>哪一个？它是秃顶还是高？</p></blockquote><p><strong>Joey Tribbiani:</strong> Umm…</p><blockquote><p>嗯…</p></blockquote><p><strong>Cecilia:</strong> Y’know what? It doesn’t matter! Because it is not true!</p><blockquote><p>你知道吗？没关系！因为这不是真的！</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Cecilia:</strong> And if it were true, how dare you come to me ask me for tips about a character that I’ve been playing for 20 years—I’ll give you a tip! (She throws her drink in his face.)</p><blockquote><p>如果这是真的，你怎么敢来问我一个我已经演了20年的角色的小贴士，我会给你一个小贴士！（她把饮料扔到他脸上。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Ms. Monroe… (She slaps him) Oh there you go. (She storms off, leaving Joey standing next to Dina. They share a nod at the ferocity of the slap they just received.)</p><blockquote><p>梦露女士…（她扇了他一巴掌）哦，好了。（她怒气冲冲地走了，留下乔伊站在迪娜旁边。他们对刚刚挨的那记耳光的凶猛表示赞同。）</p></blockquote><hr><p>🎬 <em>Central Perk, Phoebe and Rachel are still arguing over the phone.</em></p><blockquote><p>🎬 <em>中央公园，菲比和瑞秋还在电话里争吵。</em></p></blockquote><p><strong>Rachel Green:</strong> No Phoebe! You cannot get the phone that way; that’s not fair! Okay look, I have an idea. Why don’t we, why don’t we see what kind of number he has on his speed dial, and then from that we can tell who has more in common with him. And then whoever does gets the phone.</p><blockquote><p>不，菲比！你不能用那种方式接电话；这不公平！好吧，听着，我有个主意。为什么我们不，为什么我们不看看他的快速拨号盘上有什么号码，然后从中我们可以看出谁和他有更多的共同点。然后谁接电话。</p></blockquote><p><strong>Phoebe Buffay:</strong> Or, we can decide by whose ever name is closer to the word phone.</p><blockquote><p>或者，我们可以根据谁的名字更接近phone这个词来决定。</p></blockquote><p><strong>Rachel Green:</strong> I don’t think so.</p><blockquote><p>我不这么认为。</p></blockquote><p><strong>Phoebe Buffay:</strong> (handing Rachel the phone) Fine all right, but I’d bet you’d be singing another tune if we were fighting over a ratchet.</p><blockquote><p>（把电话递给瑞秋）好吧，但我敢打赌，如果我们为了棘轮打架，你肯定会唱另一首曲子。</p></blockquote><p><strong>Rachel Green:</strong> (checking the speed dial) All right, first name on the speed dial is mom.</p><blockquote><p>（检查快速拨号）好的，快速拨号上的第一个名字是妈妈。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ohh, I lost my mom to suicide.</p><blockquote><p>哦，我妈妈自杀了。</p></blockquote><p><strong>Rachel Green:</strong> Okay no way, you cannot use that to get the cute guy and the last blueberry muffin.</p><blockquote><p>好吧，不可能，你不能用它来得到那个可爱的家伙和最后一个蓝莓松饼。</p></blockquote><p><strong>Phoebe Buffay:</strong> Did I use that already today? I’m sorry.</p><blockquote><p>我今天已经用过了吗？我很抱歉。</p></blockquote><p><strong>Rachel Green:</strong> Yes okay. (Checking the speed dial again.) Well now see this isn’t telling us anything. (Reading the speed dial) Joe. Carlos. Peter. Ooh! Peter Luger! T hat’s a steak house!</p><blockquote><p>是的，好的。（再次检查快速拨号）好吧，现在看，这并没有告诉我们任何事情。（正在读快速拨号）乔。卡洛斯。彼得。哦！彼得·卢格！那是牛排馆！</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay, a meat eater. Fine, that’s one for you.</p><blockquote><p>好吧，一个肉食者。好的，这是给你的。</p></blockquote><p><strong>Rachel Green:</strong> (looking at the speed dial) Oh, I win! He’s got Barney’s on his speed dial.</p><blockquote><p>（看着快速拨号）哦，我赢了！他有巴尼的快速拨号。</p></blockquote><p><strong>Phoebe Buffay:</strong> So you don’t know that’s Barney’s the store! That can be y’know his friend’s house, or a bar. Who has Barney’s the store on their speed dial?</p><blockquote><p>所以你不知道那是巴尼的店！那可能是你认识他朋友的房子，或是酒吧。谁的快速拨号上有巴尼的商店？</p></blockquote><p><strong>Rachel Green:</strong> (showing Phoebe her phone) His new girlfriend!</p><blockquote><p>（给菲比看手机）他的新女友！</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, Monica and Chandler are eating lunch, when they start to hear a horrible screeching noise. It sounds like someone is skinning a cat.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒家，莫妮卡和钱德勒正在吃午饭，这时他们开始听到可怕的尖叫声。听起来好像有人在剥猫皮。</em></p></blockquote><p><strong>Monica Geller:</strong> What is that?</p><blockquote><p>那是什么？</p></blockquote><p><strong>Chandler Bing:</strong> I think it’s the dying cat parade.</p><blockquote><p>我想这是垂死猫游行。</p></blockquote><p><strong>Monica Geller:</strong> It sounds like it’s coming from across the street.</p><blockquote><p>听起来好像是从街对面传来的。</p></blockquote><p><strong>Chandler Bing:</strong> (turning around and looking) Oh my God!</p><blockquote><p>（转过身看）哦，我的天！</p></blockquote><p><strong>Monica Geller:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Chandler Bing:</strong> Y’know that thing that Ross was gonna do at our wedding?! He was hanging out with me yesterday and he turned to me and said, &quot;You’re half Scottish right?&quot;</p><blockquote><p>你知道罗斯在我们婚礼上要做的事吗？！他昨天和我在一起，他转向我说，“你是半个苏格兰人，对吧？”</p></blockquote><p><strong>Monica Geller:</strong> Nooo!!</p><blockquote><p>不！！</p></blockquote><p><strong>Chandler Bing:</strong> Yes!!</p><blockquote><p>是的！！</p></blockquote><p>[Cut to Ross’s apartment, he his playing the Bagpipes, badly. He’s worse than that whole keyboard thing a few years ago.]</p><blockquote><p>[转到罗斯的公寓，他吹的风笛很糟糕。他比几年前的整个键盘还糟糕。]</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, scene continued from earlier. They both get up and move to the window.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒家，场景从早些时候开始继续。他们都站起来，走向窗户。</em></p></blockquote><p><strong>Monica Geller:</strong> No, there is no way! It can not be Ross! (She looks through the window and sees Ross practicing and fumbling around with the pipes.) Unbelievable! Why is your family Scottish?!</p><blockquote><p>不，不可能！不可能是罗斯！（她透过窗户望去，看到罗斯在练习，摸索着拿着烟斗。）难以置信！为什么你的家人是苏格兰人？！</p></blockquote><p><strong>Chandler Bing:</strong> Why is your family Ross?!</p><blockquote><p>为什么你的家人是罗斯？！</p></blockquote><p><strong>Monica Geller:</strong> He cannot play at our wedding! I mean everyone will leave! I mean come on, that is just noise! It’s not even a song!</p><blockquote><p>他不能参加我们的婚礼！我是说每个人都会离开！我是说，拜托，那只是噪音！这甚至不是一首歌！</p></blockquote><p><strong>Chandler Bing:</strong> If you listen very carefully, I think its Celebration by Cool and the Gang.</p><blockquote><p>如果你仔细听的话，我想这是酷和帮派的庆祝活动。</p></blockquote><hr><p>🎬 <em>Phoebe&#39;s apartment, Phoebe is putting out some Sunflower seeds as Rachel enters.</em></p><blockquote><p>🎬 <em>菲比的公寓，瑞秋进来时，菲比正在拿出一些葵花籽。</em></p></blockquote><p><strong>Rachel Green:</strong> Hi Pheebs!</p><blockquote><p>嗨，菲比！</p></blockquote><p><strong>Phoebe Buffay:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Rachel Green:</strong> How are ya?</p><blockquote><p>你好吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Good.</p><blockquote><p>很好。</p></blockquote><p><strong>Rachel Green:</strong> Umm Pheebs, remember when we were in the coffee house we decided that I was going to keep the uh, the cute guy’s cell phone?</p><blockquote><p>嗯，菲比，还记得我们在咖啡馆的时候，我们决定让我留着那个可爱家伙的手机吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Rachel Green:</strong> And remember how I said I was going to keep it in my purse so that if it rang I could just pick it up?</p><blockquote><p>还记得我说过我要把它放在钱包里，这样如果它响了，我就可以把它捡起来吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Rachel Green:</strong> And do you remember going into my purse and stealing the phone?!</p><blockquote><p>你还记得进我钱包偷电话吗？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Ooh, now you lost me.</p><blockquote><p>哦，现在你失去了我。</p></blockquote><p><strong>Rachel Green:</strong> You stole the phone!</p><blockquote><p>你偷了电话！</p></blockquote><p><strong>Phoebe Buffay:</strong> No I didn’t!</p><blockquote><p>不，我没有！</p></blockquote><p><strong>Rachel Green:</strong> No? So you’re saying that if I called it, it wouldn’t ring?</p><blockquote><p>没有？你是说如果我打电话，它不会响？</p></blockquote><p><strong>Phoebe Buffay:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Rachel Green:</strong> Umm, okay. But while you dial, let me show you the features of my new ringing handbag. (Rachel dials her phone and Phoebe’s bag starts to ring.) Oh, it does work! (Rachel grabs the phone and takes it out of Phoebe’s handbag.)</p><blockquote><p>嗯，好的。但是当你拨电话的时候，让我给你看看我的新提包的特点。（瑞秋拨通了电话，菲比的包开始响了。）哦，它确实有用！（瑞秋抓起电话，从菲比的手提包里拿出。）</p></blockquote><p><strong>Rachel Green:</strong> Phoebe!</p><blockquote><p>菲比！</p></blockquote><p><strong>Phoebe Buffay:</strong> That is a different phone.</p><blockquote><p>那是另一部电话。</p></blockquote><p><strong>Rachel Green:</strong> Oh is it?! (She answers the cute guy’s phone.) Uhh, hello? (On her phone) Yes hi, is Rachel there? (On the other phone) Yes she is, just one moment please. (To Phoebe, holding out both phones.) It’s for me!</p><blockquote><p>哦，是吗？！（她接了帅哥的电话）喂？（打电话）是的嗨，瑞秋在吗？（另一个电话）是的，请稍等。（对菲比，伸出两部手机）是给我的！</p></blockquote><p><strong>Phoebe Buffay:</strong> That is damning evidence.</p><blockquote><p>那是该死的证据。</p></blockquote><p><em>(The cute guy’s phone rings.)</em></p><blockquote><p><em>（那个可爱的家伙的电话响了。）</em></p></blockquote><p><strong>Rachel Green:</strong> Oh my God! I bet that’s him. My digital fairy tale is about to begin. I wonder how I should be? Should I be uh (In a sexy voice) Hello? Or should I be (Happily) Hi! It’s Rach… (Phoebe knocks the phone out of Rachel’s hand, catches it, and answers it.) Would you stop doing that?!</p><blockquote><p>我的天啊！我打赌那就是他。我的数字童话即将开始。我想知道我该怎么做？我应该呃（用性感的声音）你好吗？或者我应该（高兴地）嗨！是瑞秋…（菲比把电话从瑞秋手里敲了下来，接住了，接上了。）你能不能别再这么做了？！</p></blockquote><p><strong>Phoebe Buffay:</strong> (on phone) Hello? (Listens) Yes, I’m the one who found your phone.</p><blockquote><p>（打电话）喂？（听）是的，是我找到了你的手机。</p></blockquote><p><strong>Rachel Green:</strong> Phoebe! You can’t do th…</p><blockquote><p>菲比！你不能这样做…</p></blockquote><p><strong>Phoebe Buffay:</strong> (To Rachel) Shhh! I’m on a call! (On phone) Umm well yeah, you can pick it up tonight, say 8:30? At-at my apartment. It’s umm, it’s umm 5 Morton Street, Apartment 14, umm and then maybe y’know after we can grab a bite to eat or whatever. (Listens) Okay, well okay I’ll see you then. (Listens) Bye. (Hangs up.)</p><blockquote><p>（对瑞秋）嘘！我有电话！（电话中）嗯，是的，你今晚可以去拿，比如说8:30？在我的公寓。嗯，是莫顿街5号，14号公寓，嗯，等我们可以吃点东西或其他什么的时候，也许你知道。（听）好吧，好吧，到时候见。（听）再见。（挂断。）</p></blockquote><p><strong>Rachel Green:</strong> You do know that I will be here when he comes over.</p><blockquote><p>你知道他来的时候我会在这里的。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh? And how will you know what time to come over?</p><blockquote><p>哦？你怎么知道什么时候来？</p></blockquote><p><strong>Rachel Green:</strong> You just said it!</p><blockquote><p>你刚刚说对了！</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh. Okay, well I-I was kinda hoping that I would just…be alone y’know to think about my mom and her suicide.</p><blockquote><p>哦。好吧，我有点希望我能独自一人想想我妈妈和她的自杀。</p></blockquote><p><strong>Rachel Green:</strong> Oh Phoebe!</p><blockquote><p>哦，菲比！</p></blockquote><p><strong>Phoebe Buffay:</strong> What?! That’s the first time today!</p><blockquote><p>什么？！这是今天第一次！</p></blockquote><p><strong>Rachel Green:</strong> Ohh! (Exits.)</p><blockquote><p>哦！（退出。）</p></blockquote><hr><p>🎬 <em>Silvercup Studios, Dina is at the craft services table getting some food as Joey walks up.</em></p><blockquote><p>🎬 <em>银杯工作室，乔伊走上前时，迪娜正在工艺服务台拿食物。</em></p></blockquote><p><strong>Joey Tribbiani:</strong> So you like the nachos uh? Myself I’m partial to…</p><blockquote><p>你喜欢玉米片吗？我自己我偏爱…</p></blockquote><p><strong>Dina:</strong> (interrupting) I’m 16.</p><blockquote><p>（打断一下）我16岁了。</p></blockquote><p><strong>Joey Tribbiani:</strong> See you in 2003. (She walks away.)</p><blockquote><p>2003年见。（她走开了。）</p></blockquote><p><strong>Cecilia:</strong> (walking up) You’re absolutely right they are writing me out of the show. They don’t know exactly when it’s going to happen, but apparently going to be very soon and that’s it.</p><blockquote><p>（走上前去）你说得对极了，他们把我从节目中开除了。他们不知道什么时候会发生，但显然很快就会发生，就是这样。</p></blockquote><p><strong>Joey Tribbiani:</strong> I’m so sorry. Look, if it was up to me you would never leave the show.</p><blockquote><p>我很抱歉。听着，如果由我决定，你永远不会离开这个节目。</p></blockquote><p><strong>Cecilia:</strong> Yeah, thanks.</p><blockquote><p>是的，谢谢。</p></blockquote><p><strong>Joey Tribbiani:</strong> No I mean it! I can’t believe they would do this to you! And to your fans! I mean they are going to be devastated! Heart broken! They love you so much!</p><blockquote><p>不，我是认真的！我不敢相信他们会这样对你！还有你的粉丝们！我的意思是他们会被毁灭！心碎了！他们太爱你了！</p></blockquote><p><strong>Cecilia:</strong> Oh you’re right. Thank you! What’s your name again?</p><blockquote><p>哦，你说得对。非常感谢。你叫什么名字？</p></blockquote><p><strong>Joey Tribbiani:</strong> Joey.</p><blockquote><p>乔伊。</p></blockquote><p><strong>Cecilia:</strong> Joey, well thank you. That is so sweet. Oh, excuse me. (She throws her drink on a passing writer.)</p><blockquote><p>乔伊，谢谢你。那太好了。哦，对不起。（她把饮料扔给一位路过的作家。）</p></blockquote><p><strong>The Writer:</strong> It wasn’t my decision!</p><blockquote><p>这不是我的决定！</p></blockquote><p><strong>Cecilia:</strong> (to him) I’m having a conversation here! (To Joey) You were saying?</p><blockquote><p>（对他）我在这里谈话！（对乔伊）你在说什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh yeah-ye-ye-ye-ye-ye—l-l-l-l-l-look the-the-the only reason that I, that I came up to you before was because well, I’m really nervous about-about being you. Y’know if you can help me capture the essence of the character. Y’know? Help me keep Jessica alive. Please?</p><blockquote><p>嗯，耶耶耶耶耶耶，耶耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶，耶。你知道你能否帮我抓住这个角色的本质。你知道吗？帮我让杰西卡活着。请</p></blockquote><p><strong>Cecilia:</strong> All right Joey, I will help you. Not because I-I owe it to this stupid show, but because I owe it to Jessica.</p><blockquote><p>好吧，乔伊，我会帮你的。不是因为我欠这个愚蠢的节目，而是因为我欠杰西卡。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh that’s great! Oh thank you so much!</p><blockquote><p>哦，太好了！哦，非常感谢你！</p></blockquote><p><strong>Cecilia:</strong> You’re so welcome.</p><blockquote><p>不客气。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey! Now, I’ve been watching some tapes, how’s this? (In a British accent.) &quot;Jessica Lockhart will never step foot in this place again! Ever!!&quot;</p><blockquote><p>嘿！现在，我看了一些录像带，怎么样？（用英国口音）杰西卡·洛克哈特再也不会踏进这个地方了！永远</p></blockquote><p><strong>Cecilia:</strong> Is that supposed to be me?</p><blockquote><p>那应该是我吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Cecilia:</strong> Yeah but Jessica doesn’t have an English accent.</p><blockquote><p>是的，但是杰西卡没有英国口音。</p></blockquote><p><strong>Joey Tribbiani:</strong> (shocked) I can do an English accent?! That baby’s going on my resume!</p><blockquote><p>（震惊）我会说英语口音？！那个孩子会出现在我的简历上！</p></blockquote><hr><p>🎬 <em>Central Perk, Monica and Chandler are sitting on the couch. Ross is sitting on the armchair.</em></p><blockquote><p>🎬 <em>中央公园，莫妮卡和钱德勒坐在沙发上。罗斯坐在扶手椅上。</em></p></blockquote><p><strong>Chandler Bing:</strong> Well, I feel like a snack!</p><blockquote><p>嗯，我想吃点心！</p></blockquote><p><strong>Monica Geller:</strong> Do you want some shortbread? Eh that’s Scottish like you are.</p><blockquote><p>你想要些脆面包吗？呃，你是苏格兰人。</p></blockquote><p><strong>Chandler Bing:</strong> Oh no thanks. I don’t like any thing from my Scottish heritage.</p><blockquote><p>哦，不，谢谢。我不喜欢我苏格兰血统中的任何东西。</p></blockquote><p><strong>Ross Geller:</strong> What?!</p><blockquote><p>什么？！</p></blockquote><p><strong>Chandler Bing:</strong> Well it’s just my entire family was run out of Scotland by…Vikings. Anyway, lots of bad memories. (Makes a few unintelligible noises.)</p><blockquote><p>只是我全家都被北欧海盗赶出了苏格兰。总之，有很多不好的回忆。（发出一些听不懂的声音。）</p></blockquote><p><strong>Ross Geller:</strong> Oh well, it sounds to me like your family is ready to uh, rediscover its Scottish roots.</p><blockquote><p>哦，对我来说，听起来你们家准备好了，嗯，重新发现它的苏格兰根。</p></blockquote><p><strong>Monica Geller:</strong> No! No-no they’re not. They’re still very angry! But y’know Chandler is also half-Swedish. You know what the Swedish people are famous for? Sitting down and being quiet.</p><blockquote><p>不！不，不，他们不是。他们还是很生气！但钱德勒也是半个瑞典人。你知道瑞典人以什么闻名吗？坐下来保持安静。</p></blockquote><p><strong>Ross Geller:</strong> Well yeah-yeah the Scottish history is so much more…</p><blockquote><p>嗯，是的，是的，苏格兰的历史远不止这些…</p></blockquote><p><strong>Monica Geller:</strong> (interrupting) You can not play bagpipes at the wedding!!</p><blockquote><p>（打断）你不能在婚礼上吹风笛！！</p></blockquote><p><strong>Ross Geller:</strong> How did you know about that?!</p><blockquote><p>你怎么知道的？！</p></blockquote><p><strong>Chandler Bing:</strong> We heard you play all the way from your apartment!</p><blockquote><p>我们听说你从你的公寓一路玩！</p></blockquote><p><strong>Ross Geller:</strong> Were you the ones called the cops?!</p><blockquote><p>是你叫警察的吗？！</p></blockquote><p><strong>Chandler Bing:</strong> That’s not really important right now. What is important is; while we appreciate the gesture, we just don’t feel bagpipes are appropriate for our wedding.</p><blockquote><p>现在这并不重要。重要的是,；虽然我们欣赏这种姿态，但我们觉得风笛不适合我们的婚礼。</p></blockquote><p><strong>Ross Geller:</strong> Why not?</p><blockquote><p>为什么不呢？</p></blockquote><p><strong>Chandler Bing:</strong> Because we hate them.</p><blockquote><p>因为我们讨厌他们。</p></blockquote><p><strong>Ross Geller:</strong> Come on that’s not fair! I mean you haven’t even heard me play!</p><blockquote><p>拜托，这不公平！我是说你甚至没听过我演奏！</p></blockquote><p><strong>Chandler Bing:</strong> We have heard you play.</p><blockquote><p>我们听过你演奏。</p></blockquote><p><strong>Ross Geller:</strong> No, you’ve heard my practice. Okay? Just-just give me a chance to perform for you and then decide whatever you want. And I’m not going to tell you what song I’m gonna play either. But uh, let’s just say when it’s over I’ll bet there will be a we bit o’ celebration.</p><blockquote><p>不，你听过我的练习。可以只要给我一个机会为你表演，然后决定你想要什么。我也不会告诉你我要唱哪首歌。但是，呃，让我们说，当它结束时，我打赌会有一个我们有点庆祝。</p></blockquote><hr><p>🎬 <em>Silvercup Studios, Joey is getting pointers on how to play Jessica Lockhart.</em></p><blockquote><p>🎬 <em>银杯影城，乔伊正在学习如何扮演杰西卡·洛克哈特。</em></p></blockquote><p><strong>Cecilia:</strong> So, the essence of the character is rooted in her confidence. So, when Jessica enters a room for instance, she owns everything and every person in that room. (Joey is nodding.) You try.</p><blockquote><p>所以，这个角色的本质在于她的自信。例如，当杰西卡进入一个房间时，她拥有房间里的一切和每个人。（乔伊点头）你试试看。</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay! (He scurries out the set door and re-enters, extremely impressed) All right!</p><blockquote><p>好的！（他急忙走出布景门，重新进入，印象深刻）好吧！</p></blockquote><p><strong>Cecilia:</strong> No, he already knows that he owns everything in the room! He’s not finding it out for the first time! So, try it again.</p><blockquote><p>不，他已经知道他拥有房间里的一切了！他不是第一次发现了！所以，再试一次。</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay. Okay. (He goes out and comes back in, glaring at everything.)</p><blockquote><p>好的。可以（他出去又回来，怒视着一切。）</p></blockquote><p><strong>Cecilia:</strong> Right. He’s not angry at the room either. Try it again, he owns it! He owns the room. It is his. He owns, owns, owns, owns the room! He owns it!! (Joey gets a snooty look on his face.) All right, it’s a little weird, but it’s getting better. (Joey is pleased.) Oh well, I’m gonna miss this woman so much. I don’t know what I’m going to do! I mean, it’s been 20 years of my life.</p><blockquote><p>对。他也没有在房间里生气。再试一次，他拥有它！他拥有这个房间。这是他的。他拥有，拥有，拥有，拥有这个房间！他拥有它！！（乔伊脸上带着傲慢的表情。）好吧，这有点奇怪，但正在好转。（乔伊很高兴）哦，我会非常想念这个女人的。我不知道我该怎么办！我是说，这已经是我生命中的20年了。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh well—Hey-hey! Maybe, maybe uh, maybe this is a good thing. Y’know? It’ll-it’ll give you a chance to shake things up, play different characters. You’re so talented.</p><blockquote><p>哦，嘿，嘿！也许，也许，也许这是件好事。你知道吗？这会给你一个机会改变现状，扮演不同的角色。你真有才华。</p></blockquote><p><strong>Cecilia:</strong> I am. I am, but I don’t know you know. An actor of a certain age is not that easy.</p><blockquote><p>是的。是的，但我不知道你知道。一个特定年龄的演员不是那么容易的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey that’s not true! Look at uh, look at Angela Lansb—Angelina Jolie!</p><blockquote><p>嘿，那不是真的！看看，看看安吉拉·兰斯，安吉丽娜·朱莉！</p></blockquote><p><strong>Cecilia:</strong> I probably should’ve just left years ago when the offers were pouring in, but y’know I just got so comfy here! And… Ohh, I turned down some amazing work!</p><blockquote><p>我可能几年前就应该离开了，当时有很多人向我求婚，但你知道我在这里过得很舒服！而且…哦，我拒绝了一些很棒的工作！</p></blockquote><p><strong>Joey Tribbiani:</strong> Like-like what?</p><blockquote><p>像什么？</p></blockquote><p><strong>Cecilia:</strong> Well, let’s just say if I left 15 years ago, the landscape of Mexican cinema would be very different today!</p><blockquote><p>好吧，如果我15年前离开，墨西哥电影的面貌今天会大不相同！</p></blockquote><p><strong>Joey Tribbiani:</strong> (impressed) Wow!</p><blockquote><p>（印象深刻）哇！</p></blockquote><p><strong>Cecilia:</strong> But… Well now, now’s a different time for me. (Starts to cry.)</p><blockquote><p>但是……好吧，现在对我来说是不同的时间。（开始哭了起来。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh hey come on, don’t-don’t-don’t do this! Umm, look let-let me tell you something, okay? Now when I watch you do a scene, I’m thinking, &quot;Boy, she-she is a great actress!&quot; (She’s not buying it.) Uh but-but, I am also thinking, &quot;She is hot!&quot;</p><blockquote><p>哦，嘿，别这样，别这样！嗯，听着，让我告诉你一件事，好吗？现在当我看你拍一场戏的时候，我在想，“孩子，她是一个伟大的演员！”（她不相信。）但是，我也在想，“她很性感！”</p></blockquote><p><strong>Cecilia:</strong> (intrigued) You think I’m hot?</p><blockquote><p>（好奇）你觉得我很性感？</p></blockquote><p><strong>Joey Tribbiani:</strong> You own the room. (She smiles and stares longingly into his eyes.) We should probably get-get uh…</p><blockquote><p>你拥有这个房间。（她微笑着，渴望地凝视着他的眼睛。）我们可能应该得到呃…</p></blockquote><p><strong>Cecilia:</strong> Oh yeah-yeah, we should get the… (Pause) So when Jessica kisses a man, she usually puts umm, both her hands on the man’s face. (She does so.)</p><blockquote><p>哦，是的，是的，我们应该得到…（停顿）所以当杰西卡亲吻一个男人时，她通常把她的双手放在这个男人的脸上。（她这样做了。）</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah-yeah, I noticed that! Is that ‘cause she’s so passionate?</p><blockquote><p>是的，我注意到了！那是因为她很热情吗？</p></blockquote><p><strong>Cecilia:</strong> No! It’s because that way the camera only sees her! (She takes her hands off his face.) Do you wanna try it?</p><blockquote><p>不！那是因为那样摄影机只能看到她！（她把手从他的脸上拿开）你想试试吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah! Okay. (He puts his hands on her face and they kiss.)</p><blockquote><p>是啊！可以（他把手放在她的脸上，他们接吻了。）</p></blockquote><p><strong>Cecilia:</strong> That was good, that was really good. But I-I think your hands maybe a little off, they should be maybe right like… (She grabs the back of his neck and kisses him passionately causing them to fall onto the couch.)</p><blockquote><p>很好，真的很好。但我觉得你的手可能有点松了，它们应该是正确的，比如…（她抓住他的脖子后面，热情地吻他，让它们掉到沙发上。）</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Phoebe&#39;s apartment, Phoebe and Rachel are waiting for the cute guy to show up for his cell phone. Rachel is putting on perfume by spraying it ahead of her face, and moving into it. Phoebe tries to steal some.</em></p><blockquote><p>🎬 <em>菲比的公寓，菲比和瑞秋正在等待那个可爱的家伙出现在他的手机前。瑞秋正在喷香水，喷在脸前，然后进入。菲比试图偷一些。</em></p></blockquote><p><strong>Rachel Green:</strong> Hey! Hey!</p><blockquote><p>嘿！嘿</p></blockquote><p><em>(There is a knock on the door.)</em></p><blockquote><p><em>（有人敲门。）</em></p></blockquote><p>Phoebe and **Rachel Green: **(simultaneously) Who is it?</p><blockquote><p>菲比和<strong>瑞秋·格林：</strong>（同时）是谁？</p></blockquote><p><strong>Guy:</strong> Hi! It’s Tom, I’m here to pick up the phone.</p><blockquote><p>嗨！我是汤姆，我是来接电话的。</p></blockquote><p><em>(Rachel excitedly jumps up and heads for the door.)</em></p><blockquote><p><em>（瑞秋兴奋地跳起来，朝门口走去。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Whoa! Why do you get to answer the door?</p><blockquote><p>哇！你为什么要开门？</p></blockquote><p><strong>Rachel Green:</strong> Well why shouldn’t I?!</p><blockquote><p>那我为什么不呢？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Because it’s my apartment!</p><blockquote><p>因为这是我的公寓！</p></blockquote><p><strong>Rachel Green:</strong> Well, then I get to give him the cell phone.</p><blockquote><p>那我就把手机给他。</p></blockquote><p><strong>Phoebe Buffay:</strong> Okay. All right. (Hands her the phone.) Good luck explaining all the calls to China.</p><blockquote><p>好的。好吧（把电话递给她）祝你好运，解释所有打给中国的电话。</p></blockquote><p><em>(Phoebe opens the door and Tom, an older gentleman with white hair, enters.)</em></p><blockquote><p><em>（菲比打开门，一位白发老绅士汤姆走了进来。）</em></p></blockquote><p><strong>Tom:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Phoebe Buffay:</strong> (To Rachel) Wow! How long were we arguing for?</p><blockquote><p>（对瑞秋）哇！我们争论了多久？</p></blockquote><p><strong>Rachel Green:</strong> (laughs) You’re not the man who left the cell phone.</p><blockquote><p>（笑）你不是那个留下手机的人。</p></blockquote><p><strong>Tom:</strong> No that’s my assistant.</p><blockquote><p>不，那是我的助手。</p></blockquote><p><strong>Rachel Green:</strong> Is-is he coming? (Looks hopefully out the door.)</p><blockquote><p>他会来吗？（满怀希望地看着门外。）</p></blockquote><p><strong>Tom:</strong> Umm, no.</p><blockquote><p>嗯，没有。</p></blockquote><p><strong>Phoebe Buffay:</strong> Could you-could you umm, give us one second?</p><blockquote><p>你能给我们一秒钟吗？</p></blockquote><p><strong>Tom:</strong> Sure!</p><blockquote><p>当然！</p></blockquote><p><strong>Rachel Green:</strong> We’ll be right back sir.</p><blockquote><p>我们马上回来，先生。</p></blockquote><p><strong>Tom:</strong> Sure.</p><blockquote><p>当然。</p></blockquote><p><em>(They walk into the living room.)</em></p><blockquote><p><em>（他们走进客厅。）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Wh-what do we do?</p><blockquote><p>我们该怎么办？</p></blockquote><p><strong>Rachel Green:</strong> I don’t know!</p><blockquote><p>我不知道！</p></blockquote><p><strong>Phoebe Buffay:</strong> Can you believe this? (Rachel exhales in amazement.) We were waiting for a hot guy and then an even hotter one shows up!</p><blockquote><p>你能相信吗？（瑞秋惊讶地呼气）我们在等一个帅哥，然后一个更帅哥出现了！</p></blockquote><p><strong>Rachel Green:</strong> I know! (Realizes what Phoebe said.) What?!</p><blockquote><p>我知道！（意识到菲比说的）什么？！</p></blockquote><p><strong>Phoebe Buffay:</strong> Hmm, they just don’t make ‘em like that anymore!</p><blockquote><p>嗯，他们只是不再那样做了！</p></blockquote><p><strong>Rachel Green:</strong> (turning and looking at Tom again) No-no they do but, you just have to wait.</p><blockquote><p>（转过身来，又看了看汤姆）不，不，他们会的，但是，你得等着。</p></blockquote><p><strong>Phoebe Buffay:</strong> Rachel, listen—I mean, if you let me have him then I will really owe you one.</p><blockquote><p>瑞秋，听着，我是说，如果你让我拥有他，我真的欠你一个人情。</p></blockquote><p><strong>Rachel Green:</strong> (fake disappointment) All right. All right Phoebe I will let you have him, but you owe me; you owe me big!</p><blockquote><p>（假装失望）好吧。好吧，菲比，我会让你得到他的，但你欠我的；你欠我一大笔钱！</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah! You’re such a great friend!</p><blockquote><p>是啊！你真是个好朋友！</p></blockquote><p><strong>Rachel Green:</strong> Ohh…</p><blockquote><p>哦…</p></blockquote><p><strong>Tom:</strong> So, which one of you lovely ladies am I going to take to dinner huh?</p><blockquote><p>那么，我要带你们哪位可爱的女士去吃饭呢？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh that’d be me. Sir. (Hands him the cell phone.) After you.</p><blockquote><p>哦，那就是我了。先生（把手机递给他）你先请。</p></blockquote><p><strong>Tom:</strong> Okay. Okay. (Exits and Phoebe checks him out.)</p><blockquote><p>好的。可以（离开，菲比检查了他。）</p></blockquote><p><strong>Phoebe Buffay:</strong> (whispering) Nice!</p><blockquote><p>（耳语）很好！</p></blockquote><hr><p>🎬 <em>Joey and Rachel&#39;s, Cecilia is entering the living room from Joey’s room followed by Joey.</em></p><blockquote><p>🎬 <em>乔伊和瑞秋家，塞西莉亚从乔伊的房间进入客厅，乔伊紧随其后。</em></p></blockquote><p><strong>Cecilia:</strong> Well, you certainly own that room.</p><blockquote><p>嗯，那间房间肯定是你的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Actually I rent the whole place and, I just got what you meant. Thank you.</p><blockquote><p>事实上，我租了整个房子，我才明白你的意思。非常感谢。</p></blockquote><p><em>(She laughs as Rachel enters.)</em></p><blockquote><p><em>（瑞秋进来时，她笑了。）</em></p></blockquote><p><strong>Rachel Green:</strong> Hi.</p><blockquote><p>嗨。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><em>(Rachel stops dead in her tracks when she sees whom Joey is with.)</em></p><blockquote><p><em>（当瑞秋看到乔伊和谁在一起时，她停了下来。）</em></p></blockquote><p><strong>Rachel Green:</strong> Oh my God! Oh my God!! Ohh, Jessica Lockhart!! In my apartment!! I am such a huge fan! I am such a huge fan!</p><blockquote><p>我的天啊！哦，我的上帝！！哦，杰西卡·洛克哈特！！在我的公寓里！！我是个超级粉丝！我是个超级粉丝！</p></blockquote><p><strong>Cecilia:</strong> Well, it’s nice to know that you…</p><blockquote><p>很高兴知道你…</p></blockquote><p><strong>Rachel Green:</strong> (screaming) MONICA!!!! MONICA!!!! (Runs to Monica’s.)</p><blockquote><p>（尖叫）莫妮卡！！！！莫妮卡！！！！（跑到莫妮卡家。）</p></blockquote><p><strong>Joey Tribbiani:</strong> That uh, that is my roommate Rachel.</p><blockquote><p>那是我的室友瑞秋。</p></blockquote><p><strong>Cecilia:</strong> Oh that explains all the women’s underwear.</p><blockquote><p>哦，这解释了所有女人的内衣。</p></blockquote><p><strong>Joey Tribbiani:</strong> (shrugs) Sure. Yep.</p><blockquote><p>（耸耸肩）当然。是的。</p></blockquote><p><strong>Monica Geller:</strong> (entering with Rachel) Oh my God! It’s true!! Oh my God you are so amazing! Oh my God, can I just ask you to do me oh, just one favor?</p><blockquote><p>（和瑞秋一起进来）哦，我的天啊！这是真的！！哦，我的上帝，你太棒了！我的天，我能请你帮我一个忙吗？</p></blockquote><p><strong>Cecilia:</strong> Certainly.</p><blockquote><p>当然可以。</p></blockquote><p><strong>Monica Geller:</strong> Would you slap me? Would you slap me right here in the face?! (Points to her cheek.)</p><blockquote><p>你会打我一巴掌吗？你能在这里打我一巴掌吗？！（指着她的脸颊。）</p></blockquote><p><strong>Cecilia:</strong> I’d love to, but my lawyer said I can’t do that anymore.</p><blockquote><p>我很想去，但我的律师说我不能再那样做了。</p></blockquote><p><strong>Rachel Green:</strong> God. You seem really, really nice.</p><blockquote><p>天啊。你看起来真的，真的很好。</p></blockquote><p><strong>Joey Tribbiani:</strong> Okay, bye-bye.</p><blockquote><p>好的，再见。</p></blockquote><p><strong>Rachel Green:</strong> I mean n-not-not fake at all like most famous people.</p><blockquote><p>我是说，不像大多数名人那样，一点也不假。</p></blockquote><p><strong>Joey Tribbiani:</strong> All right, here we go. (He grabs them and starts to pull them out of the apartment.)</p><blockquote><p>好了，开始吧。（他抓住他们，开始把他们从公寓里拖出来。）</p></blockquote><p><strong>Rachel Green:</strong> Okay.</p><blockquote><p>好的。</p></blockquote><p><strong>Monica Geller:</strong> (breaks away) Oh wait, just one more thing! One more minute! (To Cecilia) Umm, you’re a stupid bitch.</p><blockquote><p>（挣脱）哦，等等，还有一件事！再等一分钟！（对塞西莉亚）嗯，你是个愚蠢的婊子。</p></blockquote><p><strong>Cecilia:</strong> I really can’t slap you. (Monica walks away angrily)</p><blockquote><p>我真的不能打你耳光。（莫妮卡生气地走开了）</p></blockquote><p><strong>Rachel Green:</strong> You are so beautiful.</p><blockquote><p>你真漂亮。</p></blockquote><p><strong>Monica Geller:</strong> Nice to meet you! My God you’re great!</p><blockquote><p>很高兴认识你！天哪，你太棒了！</p></blockquote><p><strong>Joey Tribbiani:</strong> Thanks for stopping by. See ya! (Throws them out and closes the door.) (To Cecilia) I-I am so sorry. I…</p><blockquote><p>谢谢你过来。再见！（把他们扔出去，关上门。）（对塞西莉亚）我真的很抱歉。我…</p></blockquote><p><strong>Cecilia:</strong> Oh no-no-no-no, being adored. I’m used to it, don’t worry about it.</p><blockquote><p>哦，不，不，被崇拜。我已经习惯了，别担心。</p></blockquote><p><strong>Joey Tribbiani:</strong> (notices something in the mail that Rachel brought in) Oh my God!</p><blockquote><p>（注意到瑞秋带来的邮件）哦，我的天！</p></blockquote><p><strong>Cecilia:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> They sent me today’s script! They never send the script!</p><blockquote><p>他们把今天的剧本寄给我了！他们从不发送脚本！</p></blockquote><p><strong>Cecilia:</strong> They don’t?</p><blockquote><p>他们没有？</p></blockquote><p><strong>Joey Tribbiani:</strong> Well no, I’m just in a coma. This must mean I have lines! (Realizes what that means.) Oh…</p><blockquote><p>不，我只是处于昏迷状态。这一定意味着我有台词！（意识到这意味着什么）哦…</p></blockquote><p><strong>Cecilia:</strong> How does it happen?</p><blockquote><p>这是怎么发生的？</p></blockquote><p><strong>Joey Tribbiani:</strong> (flipping to the last page) Ew, you get thrown from a horse into an electric fence.</p><blockquote><p>（翻到最后一页）哎呀，你被马扔到了电栅栏里。</p></blockquote><p><strong>Cecilia:</strong> Ah what?! Jessica hates horses!</p><blockquote><p>啊什么？！杰西卡讨厌马！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah well, I’m guessing after this she’s not going to be crazy about electricity either.</p><blockquote><p>是啊，我猜在这之后她也不会对电发狂了。</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, Rachel, Phoebe, Chandler, and Monica have gathered to hear Ross perform his interpretation of Celebration by Cool and the Gang on the bag pipe.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒、瑞秋、菲比、钱德勒和莫妮卡聚在一起，听罗斯表演他对《酷和袋烟斗帮的庆祝》的诠释。</em></p></blockquote><p><strong>Ross Geller:</strong> …now remember you have to imagine me in a kilt.</p><blockquote><p>……现在记住，你必须想象我穿着苏格兰短裙。</p></blockquote><p><strong>Rachel Green:</strong> (giggles) (To Ross) I can imagine you in a short plaid skirt and knee socks.</p><blockquote><p>（咯咯笑）（对罗斯）我能想象你穿着格子短裙和及膝短袜。</p></blockquote><p><strong>Ross Geller:</strong> (To Rachel) Do you wanna start telling secrets?</p><blockquote><p>（对瑞秋）你想开始讲秘密吗？</p></blockquote><p><strong>Rachel Green:</strong> No!</p><blockquote><p>不！</p></blockquote><p><strong>Ross Geller:</strong> (stands up) Now umm, remember I’m still learning.</p><blockquote><p>（站起来）嗯，记住我还在学习。</p></blockquote><p><em>(As he prepares to start, he makes several horrible noises that scares Rachel into retreat.)</em></p><blockquote><p><em>（当他准备出发时，他发出了几声可怕的声音，吓得瑞秋退缩。）</em></p></blockquote><p><strong>Ross Geller:</strong> One, two, three, four!</p><blockquote><p>一，二，三，四！</p></blockquote><p><em>(He starts. And well, Celebration was never meant to be played on the bagpipe, so even the best bag pipe players in the world would have trouble with that particular song. So of course, for a beginner like Ross, it sounds absolutely dreadful. The assembled audience minus Phoebe, are horrified. Phoebe, immune to bad music, seems to enjoy it.)</em></p><blockquote><p><em>（他开始了。好吧，庆祝活动从来就不是用风笛演奏的，所以即使是世界上最好的风笛演奏家也会对这首歌有困难。所以，当然，对于像罗斯这样的初学者来说，这听起来绝对可怕。除了菲比之外，聚集在一起的观众都感到震惊。菲比对糟糕的音乐免疫，似乎很喜欢这首歌。）</em></p></blockquote><p><strong>Ross Geller:</strong> You know the song! Sing along!</p><blockquote><p>你知道这首歌！跟着唱！</p></blockquote><p><em>(Ross resumes playing, this time accompanied by Phoebe screeching out E’s in tune with Ross. While Phoebe is singing along, Rachel is having a very difficult time keeping a straight face. Thankfully, Ross gives up after a little while.)</em></p><blockquote><p><em>（罗斯继续演奏，这一次菲比陪着罗斯尖叫出E的曲调。菲比跟着唱的时候，瑞秋很难保持直面。谢天谢地，罗斯过了一会儿就放弃了。）</em></p></blockquote><p><strong>Ross Geller:</strong> So?</p><blockquote><p>那么？</p></blockquote><p>Monica and **Chandler Bing: **No!</p><blockquote><p>莫妮卡和<strong>钱德勒·宾：</strong>不！</p></blockquote><p><em>(Ross throws the bagpipes down in disgust.)</em></p><blockquote><p><em>（罗斯厌恶地扔下风笛。）</em></p></blockquote><hr><p>🎬 <em>Silvercup Studios, a scene is being shot where Dina and Fredrick are celebrating Jessica’s horrible accident by drinking champagne.</em></p><blockquote><p>🎬 <em>银杯工作室，正在拍摄一个场景，迪娜和弗雷德里克喝香槟庆祝杰西卡的可怕事故。</em></p></blockquote><p><strong>Dina:</strong> Loosening the saddle on mother’s horse was brilliant Fredrick. And the electric fence, inspired.</p><blockquote><p>弗雷德里克很聪明，他松开了妈妈的马鞍。还有电栅栏，灵感来源。</p></blockquote><p><strong>Fredrick:</strong> Thank you sweetheart. (They clink glasses.)</p><blockquote><p>谢谢你，亲爱的。（他们碰杯。）</p></blockquote><p><strong>Dina:</strong> I can’t believe she’s really gone. Look around you, all of this is ours. (They move into kiss but; they’re stopped by Joey entering with a huge bandage wrapped around his head.)</p><blockquote><p>真不敢相信她真的走了。看看你周围，这一切都是我们的。（他们开始接吻，但乔伊头上缠着一条大绷带，阻止了他们。）</p></blockquote><p><strong>Joey Tribbiani:</strong> (as Jessica) I don’t think so.</p><blockquote><p>（扮演杰西卡）我不这么认为。</p></blockquote><p><strong>Dina:</strong> Who are you?!</p><blockquote><p>你是谁？！</p></blockquote><p><strong>Jessica Lockhart:</strong> What’s the matter Dina? Don’t you recognize your own (Does a hair flip) mother?!</p><blockquote><p>迪娜怎么了？难道你不认识你自己的母亲吗？！</p></blockquote><p><strong>The Director:</strong> Cut! That was great everybody! Thank you!</p><blockquote><p>停！大家都很好！非常感谢。</p></blockquote><p><strong>Cecilia:</strong> (running out to Joey) That was so wonderful! (Hugs him) Ohh, I think that you’re a better Jessica than I ever was!</p><blockquote><p>（跑向乔伊）太棒了！（拥抱他）哦，我觉得你是比我更好的杰西卡！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh noo…</p><blockquote><p>哦，不…</p></blockquote><p><strong>Cecilia:</strong> Well of course not, but you were very good.</p><blockquote><p>当然不是，但是你很好。</p></blockquote><p><strong>Joey Tribbiani:</strong> Thanks!</p><blockquote><p>谢谢！</p></blockquote><p><strong>Cecilia:</strong> And guess what? Good news! I got another job!</p><blockquote><p>你猜怎么着？好消息！我找到了另一份工作！</p></blockquote><p><strong>Joey Tribbiani:</strong> Great! Hey! All right! Well-well what is it?!</p><blockquote><p>太好了！嘿好吧那是什么？！</p></blockquote><p><strong>Cecilia:</strong> A film in Guadalajara!</p><blockquote><p>瓜达拉哈拉的电影！</p></blockquote><p><strong>Joey Tribbiani:</strong> The airport?</p><blockquote><p>机场？</p></blockquote><p><strong>Cecilia:</strong> No that’s La Guardia. (Joey nods in recognition.) This is Mexico.</p><blockquote><p>不，那是拉瓜迪亚。（乔伊点头表示认可）这是墨西哥。</p></blockquote><p><strong>Joey Tribbiani:</strong> Ohh. Wow! Well how-how, how will you be gone?</p><blockquote><p>哦。哇！那你怎么，怎么走？</p></blockquote><p><strong>Cecilia:</strong> Eight months.</p><blockquote><p>八个月。</p></blockquote><p><strong>Joey Tribbiani:</strong> That’s a really long time.</p><blockquote><p>那真是太长时间了。</p></blockquote><p><strong>Cecilia:</strong> Yeah, but you can come and visit me. I bet that you could uh, own a few places down there.</p><blockquote><p>是的，但是你可以来看我。我打赌你可以在下面拥有一些地方。</p></blockquote><p><strong>Joey Tribbiani:</strong> Well I tell ya, I should probably buy a place in the city first. (Realizes.) And I just got what you meant again—That is—I tell ya, that is a tricky one!</p><blockquote><p>我告诉你，我应该先在城里买个房子。（意识到）我又明白了你的意思——我告诉你，这是一个棘手的问题！</p></blockquote><p><strong>Cecilia:</strong> That is a tricky one. Well, Joey I really wanna thank you. You’ve, well you made a very difficult time for me a little less painful.</p><blockquote><p>这是个棘手的问题。乔伊，我真的很想谢谢你。你，嗯，你让我度过了一段非常艰难的时光，让我的痛苦减轻了一点。</p></blockquote><p><strong>Joey Tribbiani:</strong> Good luck.</p><blockquote><p>祝你好运。</p></blockquote><p><strong>Cecilia:</strong> You too.</p><blockquote><p>你也是。</p></blockquote><p><em>(They kiss and both put their hands on the other’s face like Jessica would do.)</em></p><blockquote><p><em>（他们亲吻对方，并像杰西卡那样把手放在对方的脸上。）</em></p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, Rachel, Phoebe, Chandler, and Monica have gathered to hear Ross perform his interpretation of Celebration by Cool and the Gang on the bag pipe. Yes, I typed that earlier. We’re seeing this again, only this time Ross as already started playing.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒、瑞秋、菲比、钱德勒和莫妮卡聚在一起，听罗斯表演他对《酷和黑帮在袋烟斗上的庆祝》的诠释。是的，我早些时候打过。我们又看到了这个，只是这次罗斯已经开始演奏了。</em></p></blockquote><p><strong>Ross Geller:</strong> You know the song! Sing along!</p><blockquote><p>你知道这首歌！跟着唱！</p></blockquote><p><strong>Phoebe Buffay:</strong> Eeee!!! Eee!! Eee!!</p><blockquote><p>Eeee！！！Eee！！Eee！！</p></blockquote><p><em>(Monica (Courtney Cox) and Chandler (Matthew Perry) are laughing. That then causes Lisa and Jennifer come out of character and start laughing hysterically. And that finally causes David Schwimmer to come out of character and start laughing as well. Matthew decides to sing along now as well.)</em></p><blockquote><p><em>（莫妮卡（考特尼·考克斯饰）和钱德勒（马修·佩里饰）都在笑。这让丽莎和詹妮弗从角色中走出来，开始歇斯底里地大笑。最后，大卫·施维默也从角色中走出来，开始大笑。马修决定现在也跟着唱。）</em></p></blockquote><p><strong>Matthew Perry:</strong> Eee!! (This causes more laughter.)</p><blockquote><p>嘿！！（这引起了更多的笑声。）</p></blockquote><p><strong>Lisa Kudrow:</strong> Do it again!</p><blockquote><p>再来一次！</p></blockquote><p><em>(Matthew mimics the sound again.)</em></p><blockquote><p><em>（马修再次模仿声音。）</em></p></blockquote><p><em>(Why was this the trailer? Well, that’s because it was an introduction into the special out takes episode that immediately followed the show. The entire out takes episode, Friends: The Stuff You’ve Never Seen can be read by following this link.)</em></p><blockquote><p><em>（为什么这是预告片？嗯，那是因为它是紧跟在节目之后的特别外卖插曲的介绍。整个外卖插曲，朋友：你从未见过的东西可以通过以下链接阅读。）</em></p></blockquote>`,735)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};